summary:
bash: cd /app && python - <<'EOF'
import mujoco, numpy as np, time
m = mujoco.MjModel.from_xml_path("model_ref.xml")
d = mujoco.MjData(m)
d.qpos += np.random.default_rng(0).normal(0,0.01,size=d.qpos.shape)
mujoco.mj_forward(m,d)
# zero timers by reading baseline
base={k:None for k in []}
for _ in range(2000): mujoco.mj_step(m,d)
tot={}
for k in dir(mujoco.mjtTimer):
    if k.startswith("mjTIMER_"):
        v=getattr(mujoco.mjtTimer,k)
        tot[k]=d.timer[v].duration
s=sum(tot.values())
for k,v in sorted(tot.items(), key=lambda x:-x[1]):
    if v>0: print(f"{k:35s} {v*1e6:10.1f} us  {100*v/s:5.1f}%")
print("total", s*1e6)
EOF

